const profiles=[
{name:'Ledger',role:'Payment Analyst',shape:'ledger',question:'Did the money<br>actually move?',scope:'Establishes the financial facts: captures, refunds, amounts, currencies, and the payment-to-order relationship.',to:'Relay',quote:'One completed $128.00 capture appears in these PayPal records. Did the store receive the event?',evidence:'Completed PayPal capture · Order #1048',boundary:'A successful payment record cannot establish whether the store updated or fulfilled the order.'},
{name:'Relay',role:'Event Tracer',shape:'relay',question:'Where did<br>the signal go?',scope:'Follows event IDs, delivery attempts, acknowledgments, and retries to locate the handoff between systems.',to:'Patch',quote:'The store returned HTTP 200 at 10:42:04. Check whether processing actually updated the order.',evidence:'Event delivery acknowledgment · HTTP 200',boundary:'An acknowledgment confirms receipt. It does not prove the store completed the database update.'},
{name:'Patch',role:'Order Reconciler',shape:'patch',question:'Where do the<br>records disagree?',scope:'Compares order state and store processing logs with the payment evidence to locate the mismatch.',to:'Prism',quote:'The database update timed out one second later. The order stayed unpaid. The cause of the timeout remains unknown.',evidence:'Store processing log · Database timeout',boundary:'Missing evidence stays missing. A recorded timeout does not prove the underlying reason it happened.'},
{name:'Prism',role:'Review Lead',shape:'prism',question:'What can we<br>safely conclude?',scope:'Challenges unsupported claims, asks for missing checks, and keeps action behind merchant approval.',to:'Relay',quote:'Receipt is not completion. Can we establish what happened after the acknowledgment?',evidence:'Event delivery + store processing log',boundary:'Agent agreement alone is not proof. Fresh records must support the outcome.'}
];
document.querySelectorAll('[data-agent]').forEach(button=>button.addEventListener('click',()=>{const i=Number(button.dataset.agent),a=profiles[i];document.querySelectorAll('[data-agent]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.getElementById('agent-label').textContent=a.name.toUpperCase()+' / '+a.role.toUpperCase();document.getElementById('agent-question').innerHTML=a.question;document.getElementById('agent-scope').textContent=a.scope;document.getElementById('consultation-avatar').className='agent-avatar '+a.shape;document.getElementById('consultation-from').textContent=a.name;document.getElementById('consultation-to').textContent=a.to;document.getElementById('consultation-quote').textContent=a.quote;document.getElementById('consultation-evidence').textContent=a.evidence;document.getElementById('agent-boundary').textContent=a.boundary;}));
document.querySelector('.bridge-toggle').addEventListener('click',event=>{const button=event.currentTarget;const connected=button.getAttribute('aria-pressed')!=='true';button.setAttribute('aria-pressed',String(connected));button.setAttribute('aria-label',connected?'Show the original mismatch':'Preview the verified connection');document.querySelector('.hero-visual').classList.toggle('connected',connected);document.querySelector('.visual-state').textContent=connected?'Connection restored':'Connection missing';document.querySelector('.store-status').textContent=connected?'Paid. Verified.':'Awaiting payment';document.querySelector('.store-detail').textContent=connected?'RECORDS AGREE · ILLUSTRATION':'ORDER UPDATE FAILED';document.querySelector('.bridge-label').textContent=connected?'Show the mismatch':'Connect the story';});
